  // เนื้อไฟล์ตั้งต้นทั้งสี่ อยู่ตรงนี้เพราะเป็นสิ่งที่ผู้ใช้อ่าน ไม่ใช่โครงสร้าง (§39)
  // เดิมฝังไว้ใน identity.svelte.ts เป็นไทยล้วน คนที่เลือกภาษาอื่นจึงเปิดสมองตัวเองมาเจอไทย
